CREATE TABLE proflab.suppliers (
    id          INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255) NOT NULL UNIQUE
);

COMMENT ON TABLE  proflab.suppliers      IS 'База поставщиков';
COMMENT ON COLUMN proflab.suppliers.id   IS 'Уникальный идентификатор (автоинкремент)';
COMMENT ON COLUMN proflab.suppliers.name IS 'Уникальное наименование поставщика';

SELECT json_agg(
    json_build_object('id', id, 'name', name)
    ORDER BY name
) AS suppliers
FROM proflab.suppliers;

