// Получаем имя файла из формы
const filename = $('On form submission').first().json['Загрузите файл'][0].filename;

// Ищем текст в круглых скобках (пробелы по краям обрежем через trim)
const match = filename.match(/\(([^)]+)\)/);
const supplierName = match ? match[1].trim() : null;

// Если поставщик в имени файла не указан — выходим сразу
if (!supplierName) {
  return {
    json: {
      status: "Поставщик не указан, измените название файла, заключите в скобки наименование поставщика",
      supplier: null,
      supplier_id: null,
      filename: filename,
      supplier_found: false
    }
  };
}

// Достаём список поставщиков из входных данных
// Структура: [{ suppliers: [{ id, name }, ...] }]
const suppliers = $input.first().json.suppliers || [];

// Проверяем, есть ли поставщик в базе
// Сравнение регистронезависимое + без учёта пробелов по краям
const normalized = supplierName.toLowerCase();
const foundSupplier = suppliers.find(s => 
  s.name && s.name.trim().toLowerCase() === normalized
);

// Формируем результат
if (foundSupplier) {
  return {
    json: {
      status: "Поставщик найден",
      supplier: foundSupplier.name,          // имя как в базе
      supplier_id: foundSupplier.id,         // id найденного поставщика
      filename: filename,
      supplier_found: true
    }
  };
} else {
  return {
    json: {
      status: "Поставщика нет в базе данных",
      supplier: supplierName,
      supplier_id: null,
      filename: filename,
      supplier_found: false
    }
  };
}

