CREATE TABLE proflab.курсы_валют (
    код_валюты TEXT PRIMARY KEY,
    значение   NUMERIC NOT NULL,
    CONSTRAINT chk_код_валюты CHECK (код_валюты IN ('EUR', 'USD', 'CNY'))
