parameters.jsCode:
const xml = $input.first().json.data;

if (!xml || typeof xml !== 'string') {
  return [{ json: { status: 'Ошибка данных', rates: [] } }];
}

const valuteBlocks = xml.match(/<Valute[^>]*>[\s\S]*?<\/Valute>/g) || [];

if (valuteBlocks.length === 0) {
  return [{ json: { status: 'Ошибка данных', rates: [] } }];
}

const wanted = ['EUR', 'USD', 'CNY'];
const rates = [];

for (const block of valuteBlocks) {
  const charCode = (block.match(/<CharCode>(.*?)<\/CharCode>/) || [])[1];
  const nominal  = (block.match(/<Nominal>(.*?)<\/Nominal>/)   || [])[1];
  const name     = (block.match(/<Name>(.*?)<\/Name>/)         || [])[1];
  const value    = (block.match(/<Value>(.*?)<\/Value>/)       || [])[1];
  const vunit    = (block.match(/<VunitRate>(.*?)<\/VunitRate>/) || [])[1];

  if (!wanted.includes(charCode)) continue;

  rates.push({
    charCode,
    name,
    nominal: parseInt(nominal, 10),
    value: parseFloat(value.replace(',', '.')),
    unitRate: parseFloat(vunit.replace(',', '.')),
  });
}

if (rates.length === 0) {
  return [{ json: { status: 'Ошибка данных', rates: [] } }];
}

const dateMatch = xml.match(/Date="(\d{2}\.\d{2}\.\d{4})"/);

return [{
  json: {
    status: 'Данные получены',
    date: dateMatch ? dateMatch[1] : null,
    rates,
  },
}];

// Получаем все элементы с ноды "Получение контента"
const items = $('Получение контента').all();
const allData = items.map(item => item.json);

// Получаем ID поставщика из ноды "Разветление по поставщикам"
const supplierId = $('Разветление по поставщикам').first().json['ID поставщика'];

// Функция проверки формата
function validateFormat(data) {
  if (!Array.isArray(data) || data.length < 2) {
    throw new Error('Формат не распознан');
  }

  const [header1, header2] = data;

  // Проверка первой строки заголовков
  const header1Checks = [
    ['__EMPTY', 'Артикул'],
    ['__EMPTY_1', 'Наименование товаров'],
    ['__EMPTY_2', 'Ставка'],
    ['__EMPTY_3', 'РУ №'],
    ['__EMPTY_4', 'Ед. изм'],
    ['__EMPTY_5', 'Цена руб./ед.изм.']
  ];

  for (const [key, expectedValue] of header1Checks) {
    if (header1[key] !== expectedValue) {
      throw new Error('Формат не распознан');
    }
  }

  // Проверка второй строки заголовков
  if (header2['__EMPTY_2'] !== 'НДС') {
    throw new Error('Формат не распознан');
  }
  if (header2['__EMPTY_5'] !== 'оптовая') {
    throw new Error('Формат не распознан');
  }
  if (header2['__EMPTY_6'] !== 'розничная') {
    throw new Error('Формат не распознан');
  }
  // __EMPTY_7 может отсутствовать
  if (header2['__EMPTY_7'] !== undefined && header2['__EMPTY_7'] !== 'мелкооптовая') {
    throw new Error('Формат не распознан');
  }

  return true;
}

// Функция нормализации ставки НДС
function normalizeVat(value) {
  // Если значение — "Без НДС" (в любом регистре и с пробелами), возвращаем 0
  if (typeof value === 'string' && value.trim().toLowerCase() === 'без ндс') {
    return 0;
  }
  // Иначе возвращаем как есть (или пустую строку)
  return value ?? '';
}

// Функция преобразования в каталог
function buildCatalog(data, supplierId) {
  const rows = data.slice(2); // Пропускаем заголовки
  const result = [];
  let category = '';

  for (const row of rows) {
    const rowKeys = Object.keys(row);

    // Определяем строку категории: только __EMPTY_1 и нет артикула
    const isCategoryRow = 
      rowKeys.length === 1 && 
      rowKeys[0] === '__EMPTY_1';

    if (isCategoryRow) {
      category = String(row.__EMPTY_1 || '').trim();
      continue;
    }

    // Пропускаем строки без артикула и наименования
    if (!row.__EMPTY && !row.__EMPTY_1) {
      continue;
    }

    // Формируем наименование с категорией
    const productName = String(row.__EMPTY_1 || '').trim();
    const fullName = category ? `${category} ${productName}`.trim() : productName;

    const product = {
      'ID поставщика': supplierId ?? '',
      'Артикул': row.__EMPTY ?? '',
      'Наименование': fullName,
      'Ставка НДС': normalizeVat(row.__EMPTY_2),
      'Рег. Номер': row.__EMPTY_3 ?? '',   // <-- добавлено поле
      'Ед. измерения': row.__EMPTY_4 ?? '',
      'Цена (оптовая)': row.__EMPTY_5 ?? '',
      'Цена (розничная)': row.__EMPTY_6 ?? '',
      'Цена (мелкооптовая)': row.__EMPTY_7 ?? ''
    };

    result.push(product);
  }

  return result;
}

// Основная логика с обработкой ошибок
try {
  validateFormat(allData);
  const catalog = buildCatalog(allData, supplierId);

  return [{
    json: {
      success: true,
      supplier_id: supplierId ?? '',
      catalog,
      totalItems: catalog.length,
      categories: [...new Set(catalog.map(item => {
        // Извлекаем категорию из начала наименования
        const parts = item['Наименование'].split(' ');
        return parts.slice(0, Math.max(1, parts.length - 5)).join(' ');
      }))]
    }
  }];

} catch (error) {
  return [{
    json: {
      success: false,
      supplier_id: supplierId ?? '',
      error: 'Формат не распознан',
      details: error.message
    }
  }];
}

// Получаем текущее время
const now = new Date();

// Добавляем 1 час
const future = new Date(now.getTime() + 60 * 60 * 1000);

// Функция для форматирования в ISO с часовым поясом +03:00
function formatWithOffset(date) {
  const offsetMinutes = 180; // +03:00 = 180 минут
  const sign = offsetMinutes >= 0 ? '+' : '-';
  const absOffset = Math.abs(offsetMinutes);
  const offsetHours = String(Math.floor(absOffset / 60)).padStart(2, '0');
  const offsetMins = String(absOffset % 60).padStart(2, '0');

  // Сдвигаем UTC время на нужный offset, чтобы получить локальное время
  const local = new Date(date.getTime() + offsetMinutes * 60 * 1000);

  const year = local.getUTCFullYear();
  const month = String(local.getUTCMonth() + 1).padStart(2, '0');
  const day = String(local.getUTCDate()).padStart(2, '0');
  const hours = String(local.getUTCHours()).padStart(2, '0');
  const minutes = String(local.getUTCMinutes()).padStart(2, '0');
  const seconds = String(local.getUTCSeconds()).padStart(2, '0');

  return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}${sign}${offsetHours}:${offsetMins}`;
}

const result = formatWithOffset(future);

return [{
  json: {
    datetime: result
  }
}];

